cd /var/tmp/loop-bench/runs/5aefd8423c13/workspace/target; cat >> src/transport/ws/validation.test.ts <<'EOF'

describe('the list_sessions frame validator', () => {
  it('accepts a bare or well-formed list_sessions, drops a client userId, and rejects a malformed limit or before', () => {
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const malformed = [
      {limit: 'ten'},
      {limit: -1},
      {limit: 1.5},
      {before: 'not-an-object'},
      {before: null},
      {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {before: {updatedAt: true, sessionId: 's1'}},
      {before: {updatedAt: Number.NaN, sessionId: 's1'}},
    ];

    expect({
      bare: validateMessage({type: 'list_sessions'}),
      full: validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'}),
      epoch: validateMessage({type: 'list_sessions', before: {updatedAt: 0, sessionId: 's1'}}),
      malformed: malformed.map(fields => validateMessage({type: 'list_sessions', ...fields}).valid),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      full: {valid: true, data: {type: 'list_sessions', limit: 10, before}},
      epoch: {valid: true, data: {type: 'list_sessions', before: {updatedAt: 0, sessionId: 's1'}}},
      malformed: Array(malformed.length).fill(false),
    });
  });
});
EOF
timeout 300 npx jest --runTestsByPath src/transport/ws/validation.test.ts 2>&1 | tail -30
